import { Injectable, Injector } from '@angular/core';
import { HttpErrorResponse } from '@angular/common/http';
import { AgentResponse, Result } from '@imunify360-api/misc';
import { NotificationsService } from 'app/services/notifications';
import { UntranslatableString, TranslateService } from 'app/utils/translate/translate.service';
import { Type } from '@angular/core';
import { LicenseState } from 'app/services/license-state';

declare const IS_WORDPRESS_PLUGIN: boolean;

@Injectable({
    providedIn: 'root',
})
export class XhrNotificator {

    constructor(
        private injector: Injector,
        private notifications: NotificationsService,
        private translate: TranslateService,
    ) {}

    showResponseErrors(response: AgentResponse | HttpErrorResponse): void {
        const messages = (response as HttpErrorResponse)?.error?.messages || (response as AgentResponse)?.messages || [];
        if (typeof IS_WORDPRESS_PLUGIN === 'boolean' &&
            IS_WORDPRESS_PLUGIN && (response as HttpErrorResponse)?.status == 0 ) {
            return;
        }
        if (typeof messages === 'string') {
            this.getTranslatedMessage(messages).then(text => {
                return this.notifications.error(UntranslatableString.for(text));
            });
            return;
        }

        if (messages.length) {
            let license = {};
            try {
                license = this.injector
                    .get<LicenseState>(LicenseState as Type<LicenseState>).license.value;
            } catch (e) {
                // license service is not available in login module
            }
            for (let msg of messages) {
                const result = (response as HttpErrorResponse)?.error?.result || (response as AgentResponse)?.result || 'error';
                this.notifications.error(msg, `notifications.${result}`, license);
            }
            return;
        }

        if ('message' in response) {
            const errorText = response.error?.text || response.error;
            let content = (new DOMParser()).parseFromString(errorText, 'text/html')['body']
                .innerText;
            if (content === '[object Object]') {
                console.log(response);
                content = 'System error';
            }
            this.notifications.error(UntranslatableString.for(content.trim()),
                `notifications.${Result.ERROR}`);
        }
    }

    private getTranslatedMessage(httpMessage: string): Promise<string> {
        try {
            return this.translate.t(httpMessage)
                .then(translated => translated)
                .catch(() => httpMessage);
        } catch (e) {
            return Promise.resolve(httpMessage);
        }
    }
}
