import { AgentResponse, ListResponseData, RequestParams } from './misc';
import { ResourceType } from './malware';
import { MdsResourceTypeMaliciousList } from './malicious';

export enum MalwareHistoryEvent {
    added_to_ignore = 'added_to_ignore',
    cleanup_done = 'cleanup_done',
    cleanup_pending = 'cleanup_pending',
    cleanup_removed = 'cleanup_removed',
    cleanup_started = 'cleanup_started',
    deleted = 'deleted',
    deleted_from_ignore = 'deleted_from_ignore',
    failed_to_cleanup = 'failed_to_cleanup',
    failed_to_delete = 'failed_to_delete',
    failed_to_delete_from_ignore = 'failed_to_delete_from_ignore',
    failed_to_ignore = 'failed_to_ignore',
    failed_to_quarantine = 'failed_to_quarantine',
    failed_to_restore_from_backup = 'failed_to_restore_from_backup',
    failed_to_restore_from_quarantine = 'failed_to_restore_from_quarantine',
    failed_to_restore_original = 'failed_to_restore_original',
    failed_to_store_original = 'failed_to_store_original',
    failed_to_submit = 'failed_to_submit',
    found = 'found',
    not_exist = 'not_exist',
    pending = 'pending',
    quarantined = 'quarantined',
    requires_myimunify_protection = 'requires_myimunify_protection',
    restore_from_backup_started = 'restore_from_backup_started',
    restored_from_backup = 'restored_from_backup',
    restored_from_quarantine = 'restored_from_quarantine',
    restored_original = 'restored_original',
    submitted_for_analysis = 'submitted_for_analysis',
    unable_to_cleanup = 'unable_to_cleanup',
}

type MalwareHistoryItemInBackend = {
    ctime: number;
    path: string;
    event: MalwareHistoryEvent;
    initiator: string;
    cause: string;
    file_owner: string;
    file_user: string;
    id: number;
    table_name?: string | null;
    table_field?: string | null;
    table_row_inf?: number | null;
    scan_id?: string | null;
    signature_id?: string | null;
} & Omit<MdsResourceTypeMaliciousList, 'snippet'>;

export class HistoryAPI {

    static list = (params: Object) => new RequestParams(['malware', 'history', 'list'], params);
}

export class MalwareHistoryItem {
    ctime: number;
    path: string;
    event: MalwareHistoryEvent;
    initiator: string;
    cause: string;
    owner: string;

    // tslint:disable:variable-name
    resource_type: ResourceType;
    app_name?: string | null;
    db_host?: string | null;
    db_port?: string | null;
    db_name?: string | null;
    table_name?: string | null;
    table_field?: string | null;
    table_row_inf?: number | null;
    signature_id?: string | null;
    constructor(item: MalwareHistoryItemInBackend) {
        this.ctime = item.ctime;
        this.path = item.path;
        this.event = item.event;
        this.initiator = item.initiator;
        this.cause = item.cause;
        this.owner = item.file_user;
        this.resource_type = item.resource_type;
        this.signature_id = item.signature_id;
        if (item.resource_type === ResourceType.db) {
            this.app_name = item.app_name;
            this.db_host = item.db_host;
            this.db_port = item.db_port;
            this.db_name = item.db_name;
            this.table_name = item.table_name || null;
            this.table_field = item.table_field || null;
            this.table_row_inf =  item.table_row_inf || null;
        }
    }
}

type MalwareHistoryListAgentResponse = AgentResponse<ListResponseData<MalwareHistoryItemInBackend>>;
