import { Component, Renderer2 } from '@angular/core';
import { Router } from '@angular/router';
import { hideAppLoader } from 'app/utils/loader/loader.utils';
import { filter, take, timeout, of, catchError } from 'rxjs';
import { AppState } from 'app/core/app.service';

@Component({
    selector: 'app',
    template: '<router-outlet></router-outlet>',
})
export class RootComponent {
    constructor(renderer: Renderer2, router: Router, appState: AppState) {
        appState.rpcReady$
            .pipe(
                filter(ready => ready),
                timeout(5000), // timeout after 5 seconds
                catchError(() => of(true)),
                take(1),
            )
            .subscribe(() => {
                hideAppLoader(renderer, router);
            });
    }
}
