import { AgentResponse, AgentResponseData, DataFrom, RequestParams } from './misc';

type DoctorAgentResponse = AgentResponse<AgentResponseData<string>>;

export class SupportAPI {
    static send(params: SupportSendRequest) {
        return new RequestParams(['support', 'send'], params);
    }
    static doctor() {
        return new RequestParams<DataFrom<DoctorAgentResponse>>(['doctor']);
    }
}

export interface SupportSendRequest {
    email: string;
    subject: string;
    description: string;
    cln: string;
    attachments?: string[];
}
