import {
    AgentResponse,
    RequestParams,
    DataFrom,
    ListResponseData,
    AgentResponseData,
} from './misc';

export interface IAnalystCleanupRequestResult {
    ticket_url: string;
}

export interface IAnalystCleanupAllowedResult {
    is_allowed: boolean;
}

export interface IAnalystCleanupRequestParams {
    email: string;
    username: string;
    message: string;
}

export interface IAnalystGetRequestsParams {
    username?: string;
    limit?: number;
    offset?: number;
}

export enum AnalystCleanupStatus {
    pending = 'pending',
    in_progress = 'in_progress',
    completed = 'completed',
}

export interface IAnalystCleanupGetRequestsItem {
    username: string;
    ticket_url: string;
    status: AnalystCleanupStatus;
    created_at: string;
    last_update: string;
    zendesk_id: string;
}

type AnalystCleanupRequestResponse = AgentResponse<AgentResponseData<IAnalystCleanupRequestResult>>;
type AnalystCleanupAllowedResponse = AgentResponse<AgentResponseData<IAnalystCleanupAllowedResult>>;
type AnalystCleanupGetRequestsResponse = AgentResponse<ListResponseData<IAnalystCleanupGetRequestsItem>>;

export class RequestedCleanupItem implements IAnalystCleanupGetRequestsItem {
    username: string;
    ticket_url: string;
    status: AnalystCleanupStatus;
    statusToShow: string;
    created_at: string;
    last_update: string;
    zendesk_id: string;

    constructor(data: IAnalystCleanupGetRequestsItem) {
        this.username = data.username;
        this.ticket_url = data.ticket_url;
        this.status = data.status;
        this.statusToShow = this.getStatusLabel(data.status);
        this.created_at = data.created_at;
        this.last_update = data.last_update;
        this.zendesk_id = data.zendesk_id;
    }

    private getStatusLabel(status: AnalystCleanupStatus): string {
        switch (status) {
            case AnalystCleanupStatus.pending:
                return 'malware.analystCleanup.statuses.pending';
            case AnalystCleanupStatus.in_progress:
                return 'malware.analystCleanup.statuses.in_progress';
            case AnalystCleanupStatus.completed:
                return 'malware.analystCleanup.statuses.completed';
            default:
                return '';
        }
    }
}

export class AnalystCleanupAPI {
    static isAllowed() {
        return new RequestParams<DataFrom<AnalystCleanupAllowedResponse>>(['analyst-cleanup', 'is-allowed'], {});
    }

    static request(params: IAnalystCleanupRequestParams) {
        return new RequestParams<DataFrom<AnalystCleanupRequestResponse>>(['analyst-cleanup', 'request'], params);
    }

    static getRequests(params: IAnalystGetRequestsParams) {
        return new RequestParams<DataFrom<AnalystCleanupGetRequestsResponse>>(['analyst-cleanup', 'get-requests'], params);
    }
}
